WITH filtered AS (SELECT id, customer_id, order_date, status, amount, discount, shipping_fee, discount * amount AS discount_times_amount, SUBSTRING(status, 1, 2) AS status_prefix, COALESCE(channel, 'UNKNOWN') AS resolved_channel FROM orders WHERE order_date > TO_DATE('2023-03-24') AND channel IS NOT DISTINCT FROM 'mobile') SELECT * FROM (SELECT id, customer_id, amount, discount FROM filtered) src UNPIVOT (metric_value FOR metric_name IN (amount, discount));
